import { writeFileSync } from "node:fs";
import { parseBenchmarkOptions } from "./options.mjs";
import { fixtureProfile } from "./protocol";
import { prepareRepresentativeFixture } from "./prepare";

const options = parseBenchmarkOptions(process.argv.slice(2));
if (!options) throw new Error("Benchmark options required");
const report = await prepareRepresentativeFixture(
  process.env.DATABASE_URL ?? "",
  process.env.BENCHMARK_OWNER_TOKEN ?? "",
  fixtureProfile(
    options.products,
    options.fulfillment,
    options.rewards,
    options.trackedStock,
  ),
);
// Path is generated by the owning harness, never a customer or HTTP argument.
writeFileSync(
  process.env.BENCHMARK_REPORT_PATH + "/fixture.json",
  JSON.stringify(report, null, 2),
);
